\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb}
\usepackage{graphicx}
\usepackage{booktabs}
\usepackage{amsthm}
\newtheorem{proposition}{Proposition}
\usepackage{cleveref}
% keep hyperref last in the preamble
\usepackage{hyperref}

\title{Evaluation of a Scale-Aware Mixing Length\\for the Stable Boundary Layer}
\author{T.~Brandsma and E.~Kallio}
\date{July 2026}

\begin{document}
\maketitle

\section{Introduction}
\label{sec:intro}
Stable boundary layers remain the weak point of
numerical weather prediction,
and mixing-length closures are the usual suspect
when near-surface temperatures drift.
\Cref{sec:method} describes the tower dataset and the
scale-aware formulation we test.

\section{Data and Method}
\label{sec:method}
We use one year of 10 Hz turbulence measurements
from a 60 m tower over flat terrain.
The scale-aware mixing length is derived from the
local gradient Richardson number,
as summarised in \cref{prop:length}.

\begin{proposition}
\label{prop:length}
Under horizontally homogeneous conditions the scale-aware
length approaches the Monin--Obukhov limit
as stability increases.
\end{proposition}

\section{Results}
\label{sec:results}
The closure removes the warm bias below 10 m
in strongly stable cases,
as anticipated from \cref{prop:length}.
\Cref{sec:intro} motivated the focus on the lowest levels;
\cref{sec:method} shows the gain is not an artefact
of the stability function.

\end{document}

